public class Main {
    public static void main(String[] args) {
        // For Loop
        for (int i = 0; i < 3; i++) {
            System.out.println("For: " + i);
        }

        // While Loop
        int count = 0;
        while (count < 3) {
            System.out.println("While: " + count);
            count++;
        }
    }
}
